"""Legacy OPP_MASTER validation rules migrated from opportunity_rules.vrl."""

from decimal import Decimal
from typing import Any


def _value(image: dict | None, field: str) -> Any:
    if image is None:
        return ""
    value = image.get(field, "")
    return "" if value is None else value


def _text(image: dict | None, field: str) -> str:
    value = _value(image, field)
    return value if isinstance(value, str) else str(value)


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _date_gte(left: str, right: str) -> bool:
    if left == "00000000" or right == "00000000":
        return False
    return left >= right


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Return every applicable validation failure in legacy rule-file order."""
    errors: list[dict] = []

    def fail(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    if event in ("INSERT", "UPDATE"):
        # OPP-001
        if not (_number(_value(record, "AMT")) >= Decimal(0)):
            fail("E3001", "Amount negative")

        # OPP-002
        if not (
            not (
                _text(record, "STAT_CD") == "W"
                and _number(_value(record, "AMT")) == Decimal(0)
            )
        ):
            fail("E3002", "Won opportunity requires amount")

        # OPP-003
        if not (
            not (
                _text(record, "STAT_CD") == "L"
                and _text(record, "LOST_RSN") == ""
            )
        ):
            fail("E3003", "Lost reason required")

        # OPP-004
        if not (
            not (
                _text(record, "STAT_CD") == "W"
                and _text(record, "CLOSE_DT") == "00000000"
            )
        ):
            fail("E3004", "Won opportunity requires close date")

    if event == "UPDATE":
        # OPP-005
        if not (
            not (
                _text(old, "STAT_CD") == "W"
                and _text(record, "STAT_CD") != "W"
            )
        ):
            fail("E3005", "Cannot reopen a won opportunity")

    if event in ("INSERT", "UPDATE"):
        # OPP-006
        status = _text(record, "STAT_CD")
        stage_pct = _number(_value(record, "STAGE_PCT"))
        stage_is_consistent = (
            (status == "P" and stage_pct == Decimal(10))
            or (status == "Q" and stage_pct == Decimal(25))
            or (status == "N" and stage_pct == Decimal(60))
            or (status == "W" and stage_pct == Decimal(100))
            or (status == "L" and stage_pct == Decimal(0))
        )
        if not stage_is_consistent:
            fail("E3006", "Stage percent inconsistent with status")

    if event == "INSERT":
        # OPP-007
        close_date = _text(record, "CLOSE_DT")
        if not (
            close_date == "00000000"
            or _date_gte(close_date, str(today))
        ):
            fail("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return True when at least one collected failure has BLOCK severity."""
    return any(error.get("severity") == "BLOCK" for error in errors)
